            '### ความหมายและองค์ประกอบ',
            '**นิติกรรม** คือการใดๆ อันทำลงโดยชอบด้วยกฎหมายและด้วยใจสมัคร มุ่งโดยตรงต่อการผูกนิติสัมพันธ์ขึ้นระหว่างบุคคล เพื่อจะก่อ เปลี่ยนแปลง โอน สงวน หรือระงับซึ่งสิทธิ (มาตรา 149)',
            '- องค์ประกอบ 4 อย่าง: (1) มีการแสดงเจตนา (2) โดยชอบด้วยกฎหมาย (3) ด้วยใจสมัคร (4) มุ่งโดยตรงต่อการผูกนิติสัมพันธ์/ก่อผลในทางกฎหมาย',
            '- ==ข้อสังเกตที่ออกสอบบ่อย==: การแสดงเจตนาที่ทำเพราะถูก "บังคับ" จนไม่มีเจตนาอิสระเลย (เช่น จับมือเซ็น) ไม่ใช่นิติกรรมเลยตั้งแต่ต้น ต่างจาก "ข่มขู่" ที่ยังมีเจตนาอยู่แต่เจตนาบกพร่อง (เป็นแค่โมฆียะ)',
            '### การแสดงเจตนาที่บกพร่อง',
            '- **เจตนาลวง/สมยอม** (มาตรา 155): คู่กรณีรู้กันทั้งสองฝ่ายว่าไม่ได้ตั้งใจผูกพันจริง → ตกเป็น**โมฆะ** ถ้าเป็นการอำพรางนิติกรรมอื่น ให้บังคับตามนิติกรรมที่ถูกอำพราง',
            '- **สำคัญผิดในสาระสำคัญแห่งนิติกรรม** (มาตรา 156): เช่น สำคัญผิดตัวทรัพย์/ตัวบุคคลคู่สัญญาที่เป็นสาระสำคัญ → **โมฆะ**',
            '- **สำคัญผิดในคุณสมบัติของบุคคล/ทรัพย์สิน** (มาตรา 157): เป็นแค่ **โมฆียะ** (เบากว่าสำคัญผิดในสาระสำคัญ) และต้องเป็นคุณสมบัติที่ตามปกติถือว่าเป็นสาระสำคัญด้วย',
            '- **กลฉ้อฉล** (มาตรา 159): ถูกหลอกลวงจนแสดงเจตนา ถ้าไม่หลอกจะไม่ทำนิติกรรมนั้นเลย → **โมฆียะ** (ต้องถึงขนาดที่ถ้าไม่มีกลฉ้อฉลจะไม่ทำนิติกรรมนั้น มิฉะนั้นเรียกได้แค่ค่าสินไหมทดแทน)',
