            '### โมฆะกรรม vs โมฆียะกรรม (จุดเปรียบเทียบที่ออกสอบเกือบทุกปี)',
            '- **โมฆะกรรม**: เสียเปล่ามาตั้งแต่ต้น เสมือนไม่เคยเกิดนิติกรรมขึ้นเลย ใครมีส่วนได้เสียก็ยกขึ้นกล่าวอ้างได้ ศาลยกขึ้นเองได้ และ**ให้สัตยาบันไม่ได้**',
