            '- **ลูกหนี้ผิดนัด**: ถ้าหนี้ถึงกำหนดชำระแล้วและเจ้าหนี้ได้เตือนแล้วลูกหนี้ยังไม่ชำระ ลูกหนี้ตกเป็นผู้ผิดนัด (มาตรา 204) — แต่ถ้า**กำหนดเวลาชำระหนี้ไว้แน่นอนตามวันแห่งปฏิทิน** ลูกหนี้ผิดนัดทันทีเมื่อไม่ชำระตามกำหนดนั้น**โดยไม่ต้องเตือน** (มาตรา 204 วรรคสอง)',
            '- **เจ้าหนี้ผิดนัด**: เมื่อลูกหนี้ขอปฏิบัติการชำระหนี้โดยชอบแล้ว แต่เจ้าหนี้ไม่ยอมรับชำระ เจ้าหนี้ตกเป็นผู้ผิดนัด (มาตรา 207) — ผลคือลูกหนี้ไม่ต้องรับผิดในความเสียหายที่เกิดขึ้นระหว่างนั้น และไม่ต้องเสียดอกเบี้ยระหว่างผิดนัด',
            '- ==ข้อสังเกต==: ผิดนัดกับผิดสัญญาไม่ใช่คำเดียวกันเป๊ะ "ผิดนัด" เน้นเรื่อง**เวลา**การชำระหนี้ ส่วนความรับผิดเพราะไม่ชำระหนี้เลย/ชำระไม่ถูกต้องเป็นเรื่องกว้างกว่านั้น (การไม่ชำระหนี้ มาตรา 213-215)',
            '- ลูกหนี้ต้องรับผิดในความเสียหายอันเกิดแต่การไม่ชำระหนี้ (ค่าสินไหมทดแทน) เว้นแต่การไม่ชำระหนี้นั้นไม่ใช่เพราะความผิดของลูกหนี้ (มาตรา 215, 217)',
            '',
            '## ลูกหนี้/เจ้าหนี้หลายคน และความระงับแห่งหนี้ (มาตรา 291-353)',
            '- **หนี้ร่วม (ลูกหนี้ร่วม)**: ถ้าลูกหนี้หลายคนต้องชำระหนี้โดยทำนองซึ่งแต่ละคนจำต้องชำระหนี้สิ้นเชิง เจ้าหนี้จะเรียกชำระหนี้จากลูกหนี้แต่คนใดคนหนึ่งสิ้นเชิงหรือแต่โดยส่วนก็ได้ตามแต่จะเลือก จนกว่าจะได้รับชำระหนี้สิ้นเชิง (มาตรา 291) — ลูกหนี้ร่วมคนหนึ่งชำระหนี้แล้ว มีสิทธิไล่เบี้ยเอาจากลูกหนี้ร่วมคนอื่นๆ ได้ตามส่วนเท่าๆ กัน เว้นแต่กำหนดไว้เป็นอย่างอื่น (มาตรา 296)',
