            '  2. **ปลดหนี้** (มาตรา 340) — เจ้าหนี้แสดงเจตนาต่อลูกหนี้ว่าจะปลดหนี้ให้',
            '  3. **หักกลบลบหนี้** (มาตรา 341) — ลูกหนี้และเจ้าหนี้ต่างเป็นหนี้กันและกันโดยมูลหนี้อันมีวัตถุเป็นอย่างเดียวกัน และหนี้ทั้งสองรายถึงกำหนดชำระแล้ว ฝ่ายใดฝ่ายหนึ่งแสดงเจตนาหักกลบลบกันได้',
            '  4. **แปลงหนี้ใหม่** (มาตรา 349) — เปลี่ยนสิ่งซึ่งเป็นสาระสำคัญแห่งหนี้ (เช่น เปลี่ยนตัวลูกหนี้/เจ้าหนี้ หรือเปลี่ยนวัตถุแห่งหนี้) ทำให้หนี้เดิมระงับไป',
            '  5. **หนี้เกลื่อนกลืนกัน** (มาตรา 353) — สิทธิและความรับผิดในหนี้รายเดียวกันตกอยู่แก่บุคคลคนเดียวกัน (เช่น ลูกหนี้รับมรดกเป็นเจ้าหนี้ของตัวเอง)',
            '',
            '## สัญญา (มาตรา 354-394 โดยประมาณ)',
            '- สัญญาเกิดขึ้นเมื่อ**คำเสนอ**กับ**คำสนอง**ถูกต้องตรงกัน (มาตรา 361-362 โดยประมาณ) คำเสนอที่มีกำหนดเวลาให้ทำคำสนอง ถ้าไม่ได้สนองภายในเวลานั้นคำเสนอเป็นอันสิ้นความผูกพัน',
            '- **มัดจำ** (มาตรา 377-378): ทรัพย์สินที่ให้ไว้เป็นหลักฐานว่าสัญญาได้ทำกันขึ้นและเป็นประกันการปฏิบัติตามสัญญา — ถ้าฝ่ายที่วางมัดจำละเลยไม่ชำระหนี้/เป็นฝ่ายผิดสัญญา อีกฝ่ายมีสิทธิริบมัดจำได้ ถ้าฝ่ายรับมัดจำเป็นฝ่ายผิดสัญญา ต้องคืนมัดจำ',
            '- ==ข้อสังเกตที่ออกสอบบ่อย==: **มัดจำ** ต่างจาก **เบี้ยปรับ** (มาตรา 379-383) — เบี้ยปรับคือจำนวนเงิน/สิ่งอื่นที่ตกลงกันไว้ล่วงหน้าว่าจะให้ในกรณีไม่ชำระหนี้หรือชำระหนี้ไม่ถูกต้อง ศาลมีอำนาจลดเบี้ยปรับที่สูงเกินส่วนลงได้ (มาตรา 383) แต่**ริบมัดจำศาลลดไม่ได้**',
            '',
            '## จัดการงานนอกสั่ง (มาตรา 395-405)',
            '- ผู้ใดเข้าจัดการงานของบุคคลอื่นโดยเขามิได้ว่าขานวานใช้ให้ทำ หรือโดยมิได้มีสิทธิที่จะทำการงานนั้นแทนเขาได้ด้วยประการอื่น ต้องจัดการงานนั้นไปในทางที่สมประโยชน์แก่ตัวการ ตามความประสงค์อันแท้จริงของตัวการ (มาตรา 395)',
            '',
            '## ลาภมิควรได้ (มาตรา 406-419)',
            '- บุคคลใดได้ทรัพย์สิ่งใดมาโดยปราศจากมูลอันจะอ้างกฎหมายได้ และเป็นทางให้บุคคลอีกคนหนึ่งเสียเปรียบ บุคคลนั้นจำต้องคืนทรัพย์ให้แก่เขา (มาตรา 406) — หลักการง่ายๆ คือ "ได้มาโดยไม่มีสิทธิ ทำให้คนอื่นเสียเปรียบ ต้องคืน"',
