            '## ละเมิด (มาตรา 420-437 หลักทั่วไป, 448 อายุความ)',
            '- **นิยาม** (มาตรา 420): "ผู้ใดจงใจหรือประมาทเลินเล่อ ทำต่อบุคคลอื่นโดยผิดกฎหมายให้เขาเสียหายถึงแก่ชีวิต ร่างกาย อนามัย เสรีภาพ ทรัพย์สิน หรือสิทธิอย่างหนึ่งอย่างใด ผู้นั้นทำละเมิดจำต้องใช้ค่าสินไหมทดแทน"',
            '### องค์ประกอบของละเมิด',
