            '- (3) เป็นการกระทำโดยผิดกฎหมาย',
            '- (4) ทำให้ผู้อื่นเสียหายแก่ชีวิต ร่างกาย อนามัย เสรีภาพ ทรัพย์สิน หรือสิทธิอย่างหนึ่งอย่างใด',
            '- (5) มีความสัมพันธ์ระหว่างการกระทำกับความเสียหาย (ความเป็นเหตุเป็นผล)',
            '- ==ข้อสังเกตที่ออกสอบบ่อย==: **จงใจ** คือรู้สำนึกถึงผลของการกระทำและประสงค์ต่อผล ส่วน **ประมาทเลินเล่อ** คือไม่ใช้ความระมัดระวังตามวิสัยและพฤติการณ์ที่บุคคลทั่วไปในภาวะเช่นนั้นจะพึงมี ทั้งที่อาจใช้ความระมัดระวังเช่นว่านั้นได้แต่หาได้ใช้ไม่',
