            '- เจ้าของทรัพย์สินมีสิทธิใช้สอย จำหน่าย ได้ดอกผล และติดตามเอาคืนซึ่งทรัพย์สินของตนจากบุคคลผู้ไม่มีสิทธิจะยึดถือไว้ ทั้งมีสิทธิขัดขวางไม่ให้ผู้อื่นสอดเข้าเกี่ยวข้องกับทรัพย์สินนั้นโดยมิชอบด้วยกฎหมาย (มาตรา 1336)',
