            '',
            '## ภาระจำยอม และทรัพยสิทธิอื่นในอสังหาริมทรัพย์ (มาตรา 1387-1434)',
            '- **ภาระจำยอม** (มาตรา 1387): อสังหาริมทรัพย์ (ภารยทรัพย์) ต้องตกอยู่ในภาระบางอย่างเพื่อประโยชน์แก่อสังหาริมทรัพย์อื่น (สามยทรัพย์) เช่น ทางภาระจำยอม (ทางเดินผ่าน)',
            '- **สิทธิอาศัย** (มาตรา 1402): สิทธิอยู่อาศัยในโรงเรือนของผู้อื่นโดยไม่ต้องเสียค่าเช่า',
