            '',
            '## การสมรส (มาตรา 1448-1461)',
            '- เงื่อนไขการสมรส: ชายหญิงต้องมีอายุ**17 ปีบริบูรณ์**ขึ้นไป (มาตรา 1448) ไม่เป็นญาติสืบสายโลหิตโดยตรงหรือพี่น้องร่วมบิดามารดา/ร่วมแต่บิดาหรือมารดา (มาตรา 1450) ไม่เป็นคู่สมรสของบุคคลอื่นอยู่ (มาตรา 1452 — ห้ามสมรสซ้อน)',
            '- การสมรสต้องจดทะเบียน (มาตรา 1457) — ก่อนหน้านี้กฎหมายกำหนดให้สมรสได้เฉพาะชายหญิง ปัจจุบันมีกฎหมายสมรสเท่าเทียม (พ.ร.บ.แก้ไขเพิ่มเติม ป.พ.พ. ฉบับที่ 24) ขยายให้บุคคลสองคนสมรสกันได้โดยไม่จำกัดเพศ — ==จุดนี้เป็นกฎหมายที่แก้ไขล่าสุด ควรตรวจสอบตัวบทปัจจุบันให้แน่ใจก่อนใช้สอบจริงเสมอ==',
            '',
            '## ทรัพย์สินระหว่างสามีภริยา (มาตรา 1469-1493)',
            '- **สินส่วนตัว** (มาตรา 1471): (1) ทรัพย์สินที่ฝ่ายใดฝ่ายหนึ่งมีอยู่ก่อนสมรส (2) ทรัพย์สินที่เป็นเครื่องใช้สอยส่วนตัว/เครื่องประกอบอาชีพ (3) ทรัพย์สินที่ฝ่ายใดฝ่ายหนึ่งได้มาระหว่างสมรสโดยการรับมรดกหรือโดยการให้โดยเสน่หา (4) ของหมั้น',
            '- **สินสมรส** (มาตรา 1474): ทรัพย์สินที่คู่สมรสได้มาระหว่างสมรส (นอกเหนือจากสินส่วนตัว) รวมถึงที่ได้มาโดยพินัยกรรม/การให้เป็นหนังสือที่ระบุว่าเป็นสินสมรส และดอกผลของสินส่วนตัว',
            '- ==ข้อสังเกตที่ออกสอบบ่อย==: **ดอกผลของสินส่วนตัวถือเป็นสินสมรส** (เช่น ดอกเบี้ยจากเงินฝากที่เป็นสินส่วนตัว) การจัดการสินสมรสบางประเภท (เช่น ขาย จำนอง ให้เช่าซื้ออสังหาริมทรัพย์) ต้องได้รับความยินยอมจากคู่สมรสอีกฝ่าย (มาตรา 1476)',
            '',
            '## การหย่า และบิดามารดา-บุตร (มาตรา 1501-1598)',
            '- การหย่าทำได้ 2 ทาง: **หย่าโดยความยินยอม** (ต้องทำเป็นหนังสือและมีพยาน 2 คน จดทะเบียนหย่า) และ**หย่าโดยคำพิพากษาศาล** (ต้องมีเหตุตามที่กฎหมายกำหนด เช่น อุปการะเลี้ยงดูหรือยกย่องผู้อื่นฉันภริยา/สามี, ทำร้ายทารุณ, ทิ้งร้าง)',
