            '- จากธรรมชาติ: เกิด (ม.15 ทำให้มีสภาพบุคคล), ตาย (ม.15 ทำให้สภาพบุคคลสิ้นสุด + มรดกตกทอด ม.1599), ระยะเวลาผ่านไป (บรรลุนิติภาวะ ม.19 / เป็นผู้ไม่อยู่ ม.48 / สาบสูญ ม.61 / ขาดอายุความ ม.193/9)',
