            '- ต้นร่างภาษาอังกฤษ: "Juristic acts are voluntary lawful acts, the immediate purpose of which is to establish between persons relations, to create, modify, transfer, preserve or extinguish rights." ได้รับอิทธิพลจาก Art. 944 ประมวลกฎหมายแพ่งอาร์เจนตินา (ผ่านทางประมวลกฎหมายแพ่งเยอรมัน/ญี่ปุ่นซึ่งเป็นต้นแบบของ ป.พ.พ. ไทย)',
            '',
            '## ลักษณะของนิติกรรม (6 ข้อ)',
