            '2. **เป็นการกระทำที่ชอบด้วยกฎหมาย** — บนฐาน "หลักอิสระในทางแพ่ง" (Private Autonomy) ตาม**มาตรา 151** (ตกลงต่างจากบทบัญญัติกฎหมายได้ ถ้าไม่ใช่กฎหมายเกี่ยวกับความสงบเรียบร้อยหรือศีลธรรมอันดี ไม่เป็นโมฆะ)',
            '3. **กระทำโดยใจสมัคร** — ตัดสินใจเอง ไม่ถูกหลอกลวง/บังคับ/สำคัญผิด ถ้าไม่ใจสมัคร นิติกรรมอาจเป็นโมฆะหรือโมฆียะ',
            '4. **มุ่งโดยตรงต่อผลทางกฎหมาย "ระหว่างบุคคล"** (ประเด็นถกเถียงในวงวิชาการ) — ส่วนใหญ่ (เสนีย์ ปราโมช, หยุด แสงอุทัย, อักขราทร จุหารัตน ฯลฯ) มองว่า**ครอบครองปรปักษ์ไม่ใช่นิติกรรม** เพราะเป็นการกระทำต่อตัวทรัพย์ ไม่ใช่นิติสัมพันธ์ระหว่างบุคคล (ฎีกา 17,18/2497) — แต่**กิตติศักดิ์ ปรกติ**เห็นต่างว่าครอบครองปรปักษ์ก็มุ่งผลทางกฎหมายและมีผู้ถูกกระทบสิทธิ (เจ้าของเดิม) จึงน่าจะเป็นนิติกรรมได้เช่นกัน',
