            '',
            '## นิติกรรมและการแสดงเจตนาอื่นๆ ที่ไม่ใช่นิติกรรม',
            'นิติกรรมต้องมีสองลักษณะร่วมกัน: (1) ผู้แสดงเจตนาประสงค์ต่อผลทางกฎหมาย (2) กฎหมายรับรองให้มีผลตามความประสงค์นั้น — ตัวอย่างที่**ไม่ใช่**นิติกรรม (มีการแสดงเจตนา แต่กฎหมายไม่ถือความประสงค์เป็นสาระสำคัญ): มาตรา 1317 (ใช้สัมภาระผู้อื่นทำของขึ้นใหม่), มาตรา 1382 (ครอบครองปรปักษ์), มาตรา 1324 (ผู้เก็บได้ซึ่งทรัพย์สินหายเรียกรางวัล) — เป็นเพียงข้อเท็จจริงที่ก่อผลทางกฎหมายโดยทั่วไปเท่านั้น',
            '',
            '## การแบ่งประเภทของนิติกรรม',
            '- **แบ่งตามฝ่ายในการแสดงเจตนา**: (1) ฝ่ายเดียว (Unilateral) — เช่น พินัยกรรม, สละกรรมสิทธิ์, บอกเลิกสัญญา, บอกล้างโมฆียะกรรม, ปลดหนี้ (2) สองฝ่าย (Bilateral) — สัญญาต่างๆ (คำเสนอ/คำสนองเดี่ยวๆ ยังไม่ใช่นิติกรรม จนกว่าจะรวมกันเป็นสัญญา) (3) หลายฝ่าย (Multilateral) — ก่อตั้งห้างหุ้นส่วน/บริษัท/สมาคม',
            '- **แบ่งตามเวลาที่เป็นผล**: inter vivos (ผลเมื่อผู้ทำยังมีชีวิต เช่น สัญญาทั่วไป) กับ mortis causa (ผลเมื่อผู้ทำตายแล้ว เช่น พินัยกรรม, ประกันชีวิต)',
            '- **แบ่งตามค่าตอบแทน**: มีค่าตอบแทน (Commutative เช่น สัญญาซื้อขาย) กับ ไม่มีค่าตอบแทน (Gratuitous เช่น ให้โดยเสน่หา, ยืมใช้คงรูป, ฝากทรัพย์ไม่มีบำเหน็จ)',
