            '### ผลของนิติกรรมที่เป็นโมฆะ (4 ผล)',
            '1. **เสียเปล่า** — ไม่ก่อผลทางกฎหมายใดๆ',
            '2. **ผู้มีส่วนได้เสียยกขึ้นกล่าวอ้างได้** — คู่กรณี ทายาท เจ้าหนี้ ฯลฯ',
            '3. **ไม่อาจให้สัตยาบันได้** (ต่างจากโมฆียะกรรมซึ่งให้สัตยาบันได้)',
            '4. **สิ่งที่ให้กันไปต้องคืนตามหลักลาภมิควรได้** (มาตรา 406-419): เงิน — คืนเต็มจำนวน เว้นแต่รับไว้โดยสุจริตคืนเท่าที่เหลืออยู่ (**ม.412**); ทรัพย์อื่นที่รับไว้โดยสุจริต — คืนตามสภาพที่เป็นอยู่ (**ม.413**); ทรัพย์คืนไม่ได้เพราะพ้นวิสัย (**ม.414**) — สุจริตคืนเท่าที่เหลือ ทุจริตคืนเต็มจำนวน; ชำระหนี้ฝ่าฝืนกฎหมาย/ศีลธรรม เรียกคืนไม่ได้ (**ม.411**); ชำระหนี้ตามอำเภอใจทั้งที่รู้ว่าไม่มีหน้าที่ชำระ เรียกคืนไม่ได้ (**ม.407**)',
            '### ประเภทของโมฆะกรรม',
            '- **โมฆะทั้งหมด** (ม.173 หลัก) — ปกตินิติกรรมที่มีส่วนใดเป็นโมฆะจะตกเป็นโมฆะทั้งฉบับ',
            '- **โมฆะบางส่วน** (ม.173 ข้อยกเว้น) — หากพฤติการณ์บ่งชี้ว่าคู่กรณีตั้งใจให้ส่วนที่สมบูรณ์แยกออกจากส่วนที่โมฆะได้ เช่น กู้เงินดอกเบี้ยเกินอัตรา — เฉพาะดอกเบี้ยส่วนเกินตกเป็นโมฆะ ต้นเงินและสัญญากู้ยังสมบูรณ์',
            '- **โมฆะแปลงรูป** (**มาตรา 174**) — นิติกรรมที่โมฆะเพราะเหตุ "แบบ" เท่านั้น อาจแปลงเป็นนิติกรรมประเภทอื่นที่สมบูรณ์ได้ หากเข้าใจได้ว่าคู่กรณีตั้งใจเช่นนั้นหากรู้ล่วงหน้าว่าจะเป็นโมฆะ เช่น สัญญาซื้อขายที่ดินที่ทำเป็นหนังสือแต่ไม่จดทะเบียน (โมฆะตาม ม.456) อาจแปลงรูปเป็นสัญญาเช่าซื้อซึ่งทำเป็นหนังสือกันเองก็สมบูรณ์แล้ว (ม.572) — เฉพาะโมฆะเพราะแบบเท่านั้นที่แปลงรูปได้ โมฆะเพราะวัตถุประสงค์/ความสามารถแปลงรูปไม่ได้',
            '',
            '## 5.2 โมฆียะกรรม (Voidable Juristic Act)',
            '**โมฆียะกรรม** คือนิติกรรมที่กฎหมายถือว่าสมบูรณ์จนกว่าจะถูกบอกล้าง',
            '### เหตุแห่งความเป็นโมฆียะ',
