            '3. กลฉ้อฉลถึงขนาด (**มาตรา 159**)',
            '4. ข่มขู่ (**มาตรา 164**)',
            '5. กรณีอื่น เช่น สำคัญผิดตัวคู่สมรส (**มาตรา 1505**)',
