            '### ผล: (1) สมบูรณ์จนกว่าจะบอกล้าง (2) อาจถูกบอกล้างได้ (3) อาจให้สัตยาบันได้',
            '### การบอกล้างโมฆียะกรรม',
            '**ผู้มีสิทธิบอกล้าง (มาตรา 175)**: (ก) บุคคลที่ทำนิติกรรมเพราะไม่มีความสามารถ — ผู้เยาว์บอกล้างได้เมื่อบรรลุนิติภาวะ (ก่อนนั้นบอกล้างได้ถ้าได้รับความยินยอมจากผู้แทนโดยชอบธรรม), คนไร้ความสามารถ/เสมือนไร้ความสามารถ เมื่อศาลถอนคำสั่ง, คนวิกลจริต เมื่อจริตไม่วิกล (ข) ผู้แทนโดยชอบธรรม/ผู้อนุบาล/ผู้พิทักษ์ (ค) ผู้แสดงเจตนาบกพร่อง (สำคัญผิด/ถูกกลฉ้อฉล — เมื่อรู้ความจริง; ถูกข่มขู่ — เมื่อพ้นจากการข่มขู่) (ง) ทายาทของบุคคลตาม (ก)/(ค) เท่านั้น (ไม่รวมทายาทของ (ข))',
            '**วิธีบอกล้าง (มาตรา 178)**: เป็นการแสดงเจตนาฝ่ายเดียวที่ต้องมีผู้รับ ต้องแสดงต่อคู่กรณีอีกฝ่ายที่ตัวแน่นอนโดยชัดแจ้ง ใช้หลักการมีผลของการแสดงเจตนาปกติ (ม.168/169)',
            '**ผลของการบอกล้าง (มาตรา 176)**: นิติกรรมตกเป็นโมฆะตั้งแต่เริ่มแรก คู่กรณีกลับคืนสู่ฐานะเดิม (พ้นวิสัยกลับคืนให้ชดใช้ค่าเสียหายแทน) — ==ข้อสังเกต==: แม้กฎหมายบัญญัติให้ "ถือเป็นโมฆะ" แต่ผลจริงคือ "กลับคืนสู่ฐานะเดิม/ชดใช้ค่าเสียหาย" ไม่ใช่หลักลาภมิควรได้แบบโมฆะกรรมทั่วไป — ผลต่อบุคคลภายนอก: กรณีกลฉ้อฉล บุคคลภายนอกสุจริตอย่างเดียวก็คุ้มครองแล้ว (ม.160); กรณีทั่วไป ต้องสุจริต**และ**เสียค่าตอบแทนจึงคุ้มครอง (ม.1329)',
            '**กำหนดเวลาบอกล้าง (มาตรา 181)**: ภายใน **1 ปี**นับแต่เวลาที่อาจให้สัตยาบันได้ (คือเมื่อเหตุแห่งโมฆียะหมดสิ้นไปตาม ม.179 เช่น ผู้เยาว์บรรลุนิติภาวะ, ผู้สำคัญผิด/ถูกกลฉ้อฉลรู้ความจริง) **และ**ไม่เกิน **10 ปี**นับแต่วันทำนิติกรรม (ต้องอยู่ในทั้งสองกำหนดพร้อมกัน — เช่น ทำนิติกรรมปี 2556 เพิ่งรู้ความจริงปลายปี 2565 จะมีเวลาบอกล้างจริงเพียงไม่ถึง 1 ปี เพราะติดเพดาน 10 ปีนับแต่วันทำนิติกรรมก่อน)',
