            '**ผู้มีสิทธิให้สัตยาบัน (มาตรา 177)** = บุคคลตาม ม.175 เช่นเดียวกับผู้มีสิทธิบอกล้าง — แต่ต่างจากการบอกล้างตรงที่ **ผู้เยาว์/คนเสมือนไร้ความสามารถที่ยังไม่พ้นสภาวะนั้น แม้ได้รับความยินยอมจากผู้แทน/ผู้พิทักษ์ก็ให้สัตยาบันไม่ได้** (ม.179) ต้องรอพ้นสภาวะก่อนเท่านั้น (ต่างจากการบอกล้างซึ่งทำได้แม้ยังไม่พ้นสภาวะ หากได้รับความยินยอม)',
            '**วิธีให้สัตยาบัน**: โดยชัดแจ้ง (ม.178) หรือโดยปริยาย (**มาตรา 180** — เช่น ชำระหนี้ทั้งหมด/บางส่วน, เรียกให้ชำระหนี้, แปลงหนี้ใหม่, ให้ประกันหนี้, โอนสิทธิ/ความรับผิด)',
