            '### การคำนวณระยะเวลา (มาตรา 193/2, 193/4-6)',
            '- โดยหลักคำนวณเป็น**วัน** (วัน = 00.00-24.00 น. รวม 24 ชม.) เว้นแต่ตกลงคำนวณหน่วยสั้นกว่าวันได้ — ในทางคดี/ราชการ/ธุรกิจ "วัน" หมายถึงเวลาทำการตามที่กำหนด (ม.193/4)',
            '- กำหนดเป็น**สัปดาห์/เดือน/ปี** → คำนวณตามปฏิทินสุริยคติ (ม.193/5 ว.1) สัปดาห์เริ่มวันอาทิตย์จบวันเสาร์ ปีเริ่ม 1 ม.ค. จบ 31 ธ.ค.',
            '- กำหนดเป็น**เดือนและวัน/ส่วนของเดือน** → นับเดือนเต็มก่อนแล้วนับวัน โดยถือส่วนของเดือน = 30 วัน (ม.193/6 ว.1)',
            '- กำหนดเป็น**ส่วนของปี** → คำนวณเป็นเดือนก่อน (ถือเดือนละ 30 วัน) ส่วนที่เหลือคำนวณเป็นวัน (ม.193/6 ว.2)',
            '### การสิ้นสุดของระยะเวลา',
            '- เมื่อเสร็จสิ้นตามเวลาที่กำหนด (หน่วยสั้นกว่าวัน)',
