            '- ไม่ได้เริ่มนับแต่วันต้นแห่งหน่วยนั้น → สิ้นสุดในวันก่อนหน้าจะถึงวันตรงกับวันเริ่มนับของสัปดาห์/เดือน/ปีถัดไป (ม.193/5 ว.2)',
