            '- ==ข้อสังเกต==: บทบัญญัติที่ใช้คำว่า "นับแต่" (เช่น ม.48, 61, 181, 474) หมายถึงวันนั้นเป็นวันเริ่มต้นแห่งระยะเวลา แต่การนับยังต้องไม่นับวันแรกรวม (เริ่มนับวันถัดไปตาม ม.193/3 ว.2)',
            '',
            '## 7.2 อายุความ (Prescription)',
            '**มาตรา 193/9**: สิทธิเรียกร้องใดไม่ได้บังคับภายในระยะเวลาที่กฎหมายกำหนด สิทธิเรียกร้องนั้น**ขาดอายุความ** — เหตุผล: ป้องกันความไม่แน่นอนที่หนี้จะถูกบังคับหรือไม่ตลอดไป และป้องกันการฟ้องร้องที่ยืดเยื้อ',
            '- **มาตรา 193/11**: อายุความเป็นกฎหมายเกี่ยวกับความสงบเรียบร้อยฯ คู่สัญญาจะตกลงงดใช้/ขยาย/ย่นอายุความไม่ได้',
            '- **อายุความสะดุดหยุดลง** (มาตรา 193/14-15): เมื่อมีเหตุตามกฎหมาย ต้องเริ่มนับใหม่ทั้งหมด ระยะเวลาก่อนหน้าไม่นับรวม — เหตุ: (ก) โดยการกระทำของลูกหนี้ — รับสภาพหนี้เป็นหนังสือ ชำระหนี้บางส่วน ชำระดอกเบี้ย ให้ประกัน หรือกระทำการอันแสดงว่ายอมรับสภาพหนี้โดยปริยาย (พูดรับด้วยวาจาเฉยๆ ไม่นับ) (ข) โดยการใช้สิทธิของเจ้าหนี้ — ฟ้องคดี ยื่นคำขอรับชำระหนี้ในคดีล้มละลาย มอบข้อพิพาทให้อนุญาโตตุลาการ',
            '### กำหนดอายุความ',
            '- **2 ปี** (มาตรา 193/34-35) — เช่น ผู้ประกอบการค้า/อุตสาหกรรม/หัตถกรรมเรียกค่าของ/ค่าการงาน; ผู้ประกอบวิชาชีพอิสระ (วิศวกร สถาปนิก ผู้สอบบัญชี) เรียกค่าการงาน',
            '- **5 ปี** (มาตรา 193/33) — ดอกเบี้ยค้างชำระ, เงินผ่อนทุนคืนเป็นงวด, ค่าเช่าทรัพย์สินค้างชำระ, เงินเดือน/เงินบำนาญ/ค่าอุปการะเลี้ยงดูที่จ่ายเป็นระยะ',
            '- **10 ปี** (มาตรา 193/30-32) — **หลักทั่วไป**เมื่อไม่มีกฎหมายกำหนดไว้เฉพาะ; สิทธิเรียกร้องของรัฐเรื่องภาษีอากร; สิทธิเรียกร้องตามคำพิพากษาถึงที่สุด/สัญญาประนีประนอมยอมความ (ไม่ว่าสิทธิเดิมมีอายุความเท่าใด)',
            '- **กรณีพิเศษอื่นๆ**: ละเมิด 1 ปี (นับแต่รู้ถึงการละเมิดและรู้ตัวผู้ต้องรับผิด หรือ 10 ปีนับแต่วันทำละเมิด แล้วแต่อย่างใดถึงก่อน — ม.448); ทรัพย์ชำรุดบกพร่อง 1 ปีนับแต่พบเห็นความชำรุด (ม.474); ร้อนสิทธิในทรัพย์ที่ซื้อขาย 3 เดือน (ม.481)',
            '### การเริ่มนับอายุความ (มาตรา 193/12)',
            '- สิทธิเรียกร้องให้กระทำการ → เริ่มนับแต่ขณะที่อาจบังคับสิทธิได้',
            '- สิทธิเรียกร้องให้งดเว้นกระทำการ → เริ่มนับแต่เวลาแรกที่ฝ่าฝืน',
            '- สิทธิที่ต้องบอกกล่าวก่อน → เริ่มนับแต่เวลาแรกที่อาจทวงถามได้ (หรือแต่ระยะเวลาที่กำหนดให้รอสิ้นสุดลง ถ้ามี)',
            '### ผลของอายุความครบกำหนด',
